"""Generate fully offline, no-CDN law explorer and source-status dashboard."""
from pathlib import Path
import sys,json,html
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'src'))
from fiscal_data.v06_law import scenario,baseline_gap
s=scenario();years=baseline_gap();policy=s['policies'];status=json.loads((ROOT/'results/v06/source_gate.json').read_text())
P=[]
for o in policy:
    terms=o['terms']; major=[]
    for k,v in terms.items():
        if k in ('rate_exclusive','threshold_usd_2028','annual_excludable_premium_limit_usd_2028','new_rate','wage_threshold_usd_2028','annual_employee_extra_rate','first_new_eligibility_year','statutory_minimum_coding_pattern_adjustment','eligible_codes','phase','caps_base_defense_BA_billions','extra_combined_rate_2030','max_deduction_tax_benefit_rate','credit_refund_formula','ceiling_applies_to','county_benchmark_ceiling_fraction_FFS'):
            major.append(f'<li><b>{html.escape(k.replace("_"," ").capitalize())}</b>: {html.escape(str(v))}</li>')
    if not major:
        major=[f'<li><b>{html.escape(k.replace("_"," "))}</b>: {html.escape(str(v))}</li>' for k,v in list(terms.items())[:4]]
    P.append(f'''<details><summary><span class="num">{o['section']}</span><span class="provtit">{html.escape(o['id'].replace('_',' ').title())}<small>{html.escape(o['score_lead'])} · from {html.escape(o['effective_date'])}</small></span><span class="status">UNSCORED</span></summary><div class="details"><p><strong>Legal anchor:</strong> {html.escape(o['legal_anchor'])}</p><ul>{''.join(major)}</ul><p class="muted">Defined research proposal, not enacted law or a scored fiscal effect.</p></div></details>''')
series=[{'y':v['fy'],'d':float(v['baseline_deficit_bn']),'gap':float(v['static_improvement_required_bn']),'gdp':float(v['baseline_nominal_gdp_bn'])} for v in years]
maxi=max(v['gap'] for v in series);coords=' '.join(f'{48+i*64:.0f},{214-v["gap"]/maxi*165:.1f}' for i,v in enumerate(series))
ticks=''.join(f'<text x="{48+i*64:.0f}" y="233" text-anchor="middle">{v["y"]}</text>' for i,v in enumerate(series))
htmltext=f'''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"/><title>FiscalRazor v0.6 • Legislative Research</title><style>
:root{{--bg:#f5f0e9;--ink:#26232b;--muted:#625c64;--red:#802b37;--gold:#af8055;--line:#d6cbc3;--card:#fffaf4}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);font:15px/1.56 system-ui,-apple-system,"Segoe UI",sans-serif;color:var(--ink)}}main{{max-width:1100px;margin:0 auto;padding:35px 25px 80px}}header{{border-bottom:2px solid var(--ink);padding-bottom:18px}}.eyebrow{{color:var(--red);text-transform:uppercase;font-size:11px;letter-spacing:.16em;font-weight:750}}h1{{font-family:Georgia,serif;font-size:clamp(38px,5vw,64px);line-height:1.08;margin:10px 0}}h2{{font:normal 30px Georgia,serif;margin:38px 0 12px}}p{{max-width:870px}}.muted{{color:var(--muted)}}.metricgrid{{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-top:25px}}.metric{{border:1px solid var(--line);padding:15px;background:var(--card);min-height:105px}}.metric small{{display:block;color:var(--muted)}}.metric b{{font-size:26px;display:block;margin:5px 0}}.cols{{display:grid;grid-template-columns:1.2fr 1fr;gap:24px}}.panel{{border:1px solid var(--line);background:var(--card);padding:21px;border-radius:3px}}details{{border-top:1px solid var(--line);background:var(--card)}}details:last-child{{border-bottom:1px solid var(--line)}}summary{{display:flex;gap:12px;align-items:center;cursor:pointer;padding:12px;list-style:none}}summary::-webkit-details-marker{{display:none}}summary:after{{content:'＋';margin-left:auto;color:var(--red)}}details[open] summary:after{{content:'−'}}.num{{font-family:Georgia,serif;font-size:22px;color:var(--red)}}.provtit{{font-weight:650}}.provtit small{{display:block;font-weight:400;color:var(--muted)}}.status{{font-size:10px;border:1px solid var(--line);padding:3px 5px;color:var(--red);letter-spacing:.08em}}.details{{padding:0 20px 16px 61px}}.details li{{margin-bottom:7px;overflow-wrap:anywhere}}svg{{width:100%;height:250px}}svg text{{font-size:11px;fill:var(--muted)}}label{{display:block;color:var(--muted);font-size:12px;margin:12px 0 5px}}input[type=range]{{width:100%;accent-color:var(--red)}}output{{display:block;font-size:25px;font-family:Georgia,serif}}table{{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}}td,th{{border-bottom:1px solid var(--line);padding:7px 10px;text-align:right}}td:first-child,th:first-child{{text-align:left}}.notice{{padding:12px;border-left:3px solid var(--red);background:#efe7e3;color:#61313b;font-size:13px}}a{{color:var(--red)}}button{{background:var(--red);color:white;border:none;padding:8px 10px;cursor:pointer}}@media(max-width:780px){{.metricgrid{{grid-template-columns:repeat(2,1fr)}}.cols{{grid-template-columns:1fr}}main{{padding:20px 15px 45px}}.status{{display:none}}}}</style></head><body><main>
<header><div class="eyebrow">Research draft · source-controlled · 6 November 2026</div><h1>FiscalRazor / v0.6</h1><p>One operational 12-provision legislative research specification, the exact federal target, and independently testable mechanisms. <strong>Not enacted. Not scored. No invented national savings.</strong></p><div class="notice">Source gate: original complete public datasets acquired here = <b>{status['materialized_originals']}</b>. Congressional and agency scoring not obtained; distributional results blocked pending real records.</div></header>
<div class="metricgrid"><div class="metric"><small>FY2036 required static improvement</small><b>$1.714T</b><small>CBO February 2026 baseline, 3% GDP target</small></div><div class="metric"><small>FY2036 flat debt ratio, one-year</small><b>$1.043T</b><small>Different frozen-baseline criterion</small></div><div class="metric"><small>Legislative mechanisms</small><b>12</b><small>Distinct legal provisions</small></div><div class="metric"><small>Score ledger</small><b>120 + 90</b><small>Unscored provision / core interaction years</small></div><div class="metric"><small>Full original data archives here</small><b>{status['materialized_originals']}</b><small>51 registered sources; 37 direct candidates</small></div></div>
<h2>Static annual target, not projected policy effects</h2><div class="panel"><svg viewBox="0 0 680 245" role="img" aria-label="CBO baseline improvement necessary to reach 3 percent GDP deficit each fiscal year"><line x1="48" x2="625" y1="214" y2="214" stroke="#aaa"/><line x1="48" x2="625" y1="50" y2="50" stroke="#ddd"/><text x="4" y="53">$1.7T</text><text x="4" y="214">$0</text><polyline points="{coords}" fill="none" stroke="#802b37" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>{ticks}</svg><p class="muted">Each observation = frozen FY CBO deficit − 3% of directly published FY GDP. It does <i>not</i> reflect enacted 2026 updates, macro feedback, or any calculated reform effect.</p></div>
<h2>Statutory mechanics · synthetic experiments only</h2><div class="cols"><div class="panel"><h3>OASDI, 2028</h3><p class="muted">For demonstration only, assume a hypothetical 2028 Social Security wage base of $192,300. That is the 2027 published base, <b>not</b> a 2028 forecast.</p><label for="wage">Annual wages: <b id="wv"></b></label><input id="wage" type="range" min="0" max="1000000" step="5000" value="350000"><p>Combined incremental payroll tax</p><output id="outPayroll"></output><p class="muted" id="outDecomp"></p></div><div class="panel"><h3>VAT credit, 2029</h3><p class="muted">Purely synthetic poverty guideline P = $20,000 (not an observed 2029 HHS value). Eligible consumption is a hypothetical taxable base.</p><label for="income">MAGI: <b id="iv"></b></label><input id="income" type="range" min="0" max="100000" step="1000" value="20000"><label for="spend">Taxable consumption: <b id="cv"></b></label><input id="spend" type="range" min="0" max="100000" step="1000" value="20000"><p>Mechanical VAT minus refundable credit</p><output id="outVat"></output><p class="muted" id="outVatDetail"></p></div></div>
<h2>The twelve proposed provisions</h2><p class="muted">Each card is a definition and implementation gate, not a quantified savings estimate. Full legal wording is in <code>legislation/ILLUSTRATIVE_FISCAL_REFORM_ACT_2027.md</code>.</p>{''.join(P)}
<h2>Next evidence gates</h2><div class="panel"><table><thead><tr><th>Proof obligation</th><th>Status</th></tr></thead><tbody><tr><td>Agency-original CSV/ZIP/PUMD bytes with SHA receipts</td><td>Not acquired</td></tr><tr><td>2026 JCT-style tax model, calibrated to SOI</td><td>Not run</td></tr><tr><td>OASI and DI 75-year joint actuarial score</td><td>Not run</td></tr><tr><td>HI/SMI reform and MA plan/payment scores</td><td>Not run</td></tr><tr><td>Actual nationally weighted household impacts</td><td>Not run</td></tr><tr><td>Independent fiscal frontier with evidence bounds</td><td>Unknown until inputs</td></tr><tr><td>Official combined CBO/JCT/SSA/CMS scoring</td><td>Not issued</td></tr></tbody></table></div>
<p class="muted">Primary sources: <a href="https://github.com/US-CBO/cbo-data">CBO machine-readable baseline</a> · <a href="https://www.ssa.gov/oact/trsum/">SSA trustees</a> · <a href="https://www.cms.gov/data-research/statistics-trends-and-reports/trustees-report-trust-funds">CMS trustees</a> · <a href="https://www2.census.gov/programs-surveys/cps/datasets/2026/march/">2026 CPS ASEC</a>. Runs entirely offline; no external UI libraries.</p></main><script>
const fmt=n=>new Intl.NumberFormat('en-US',{{style:'currency',currency:'USD',maximumFractionDigits:2}}).format(n);
function update(){{let w=Number(document.getElementById('wage').value),lo=Math.min(w,192300),high=Math.max(0,w-250000),p=.124*high,base=.002*lo,interaction=.002*high;document.getElementById('wv').textContent=fmt(w);document.getElementById('outPayroll').textContent=fmt(p+base+interaction);document.getElementById('outDecomp').textContent=`High band ${{fmt(p)}} + phase rate on base ${{fmt(base)}} + interaction ${{fmt(interaction)}}.`;
let m=Number(document.getElementById('income').value),c=Number(document.getElementById('spend').value),poverty=20000,factor=Math.min(1,Math.max(0,(3*poverty-m)/poverty)),gross=.05*c,credit=.05*poverty*factor;document.getElementById('iv').textContent=fmt(m);document.getElementById('cv').textContent=fmt(c);document.getElementById('outVat').textContent=fmt(gross-credit);document.getElementById('outVatDetail').textContent=`Gross VAT ${{fmt(gross)}}, refundable credit ${{fmt(credit)}}, credit fraction ${{(factor*100).toFixed(0)}}%. Not a predicted real household burden.`;}}
document.querySelectorAll('input[type=range]').forEach(e=>e.addEventListener('input',update));update();
</script></body></html>'''
(ROOT/'policy_workbench_v06.html').write_text(htmltext,encoding='utf-8')
print('workbench characters',len(htmltext),'cards',len(P))
